@RestController
@RequestMapping("/api/projects/{projectId}/invoices")
public class InvoiceController {

    private final InvoiceService service;

    public InvoiceController(InvoiceService service) {
        this.service = service;
    }

    @GetMapping
    public List<InvoiceResponse> list(@PathVariable Long projectId) {
        return service.listForProject(projectId);
    }

    @PostMapping
    @ResponseStatus(HttpStatus.CREATED)
    public InvoiceResponse create(@PathVariable Long projectId, @Valid @RequestBody InvoiceRequest request) {
        return service.create(projectId, request);
    }

    @GetMapping("/{invoiceId}")
    public InvoiceDetailResponse get(@PathVariable Long projectId, @PathVariable Long invoiceId) {
        return service.get(projectId, invoiceId);
    }

    @PostMapping("/{invoiceId}/line-items")
    @ResponseStatus(HttpStatus.CREATED)
    public InvoiceDetailResponse addLineItem(@PathVariable Long projectId, @PathVariable Long invoiceId,
            @Valid @RequestBody LineItemRequest request) {
        return service.addLineItem(projectId, invoiceId, request);
    }

    @PutMapping("/{invoiceId}/line-items/{lineItemId}")
    public InvoiceDetailResponse updateLineItem(@PathVariable Long projectId, @PathVariable Long invoiceId,
            @PathVariable Long lineItemId, @Valid @RequestBody LineItemRequest request) {
        return service.updateLineItem(projectId, invoiceId, lineItemId, request);
    }

    @DeleteMapping("/{invoiceId}/line-items/{lineItemId}")
    public InvoiceDetailResponse removeLineItem(@PathVariable Long projectId, @PathVariable Long invoiceId,
            @PathVariable Long lineItemId) {
        return service.removeLineItem(projectId, invoiceId, lineItemId);
    }

    @PostMapping("/{invoiceId}/send")
    public InvoiceResponse send(@PathVariable Long projectId, @PathVariable Long invoiceId) {
        return service.send(projectId, invoiceId);
    }
}
package net.officefloor.hq.app.invoice;

import java.math.BigDecimal;
import java.math.RoundingMode;
import java.time.LocalDate;
import java.util.List;
import java.util.Map;
import java.util.stream.Collectors;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.client.Client;
import net.officefloor.hq.app.client.ClientRepository;
import net.officefloor.hq.app.payment.PaymentRepository;
import net.officefloor.hq.app.project.Project;
import net.officefloor.hq.app.project.ProjectRepository;
import org.springframework.http.HttpStatus;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.server.ResponseStatusException;

@Service
public class InvoiceService {

    private final InvoiceRepository invoices;
    private final ProjectRepository projects;
    private final PaymentRepository payments;
    private final ClientRepository clients;
    private final Audit audit;

    public InvoiceService(InvoiceRepository invoices, ProjectRepository projects, PaymentRepository payments,
            ClientRepository clients, Audit audit) {
        this.invoices = invoices;
        this.projects = projects;
        this.clients = clients;
        this.payments = payments;
        this.audit = audit;
    }

    @Transactional(readOnly = true)
    public List<InvoiceResponse> listForProject(Long projectId) {
        if (!projects.existsById(projectId)) {
            throw new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown project");
        }
        List<Invoice> found = invoices.findByProjectIdOrderById(projectId);
        Map<Long, BigDecimal> paid = paidByInvoice(found);
        return found.stream()
                .map(i -> InvoiceResponse.from(i, paid.getOrDefault(i.getId(), BigDecimal.ZERO)))
                .toList();
    }

    /**
     * A client's statement: every invoice across their projects with what is left to pay on each, and
     * the total they still owe. Drafts are listed but not owed, as they have not been sent.
     */
    @Transactional(readOnly = true)
    public ClientStatementResponse statementForClient(Long clientId) {
        Client client = clients.findById(clientId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown client"));
        List<Invoice> found = invoices.findByClientIdWithProject(clientId);
        Map<Long, BigDecimal> paid = paidByInvoice(found);
        List<ClientStatementResponse.Line> lines = found.stream()
                .map(i -> ClientStatementResponse.Line.from(i, paid.getOrDefault(i.getId(), BigDecimal.ZERO)))
                .toList();
        BigDecimal outstanding = lines.stream()
                .filter(l -> l.status() != InvoiceStatus.DRAFT)
                .map(ClientStatementResponse.Line::amountDue)
                .reduce(BigDecimal.ZERO, BigDecimal::add)
                .setScale(2, RoundingMode.HALF_UP);
        return new ClientStatementResponse(client.getId(), client.getName(), lines, outstanding);
    }

    private Map<Long, BigDecimal> paidByInvoice(List<Invoice> found) {
        return found.isEmpty() ? Map.of()
                : payments.sumAmountByInvoiceIds(found.stream().map(Invoice::getId).toList()).stream()
                        .collect(Collectors.toMap(PaymentRepository.InvoicePaidTotal::getInvoiceId,
                                PaymentRepository.InvoicePaidTotal::getPaid));
    }

    /**
     * Every invoice across all projects, with the name of the project each one is for, narrowed to
     * the given status when one is supplied.
     */
    @Transactional(readOnly = true)
    public List<InvoiceSummaryResponse> listAll(InvoiceStatus status) {
        List<Invoice> found =
                status == null ? invoices.findAllWithProject() : invoices.findAllWithProjectByStatus(status);
        return found.stream().map(InvoiceSummaryResponse::from).toList();
    }

    @Transactional
    public InvoiceResponse create(Long projectId, InvoiceRequest request) {
        Project project = projects.findById(projectId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown project"));
        LocalDate issued = request.issuedDate() != null ? request.issuedDate() : LocalDate.now();
        LocalDate due = request.dueDate() != null ? request.dueDate() : issued.plusDays(InvoiceRequest.DEFAULT_TERM_DAYS);
        if (due.isBefore(issued)) {
            throw new ResponseStatusException(HttpStatus.BAD_REQUEST, "Due date must not be before the issue date");
        }
        Invoice invoice = new Invoice(project, issued, due);
        if (request.amount() != null) {
            invoice.addLineItem(InvoiceRequest.SINGLE_AMOUNT_DESCRIPTION, BigDecimal.ONE, request.amount());
        }
        Invoice saved = invoices.save(invoice);
        return InvoiceResponse.from(saved, BigDecimal.ZERO);
    }

    /** A single invoice with its line items. */
    @Transactional(readOnly = true)
    public InvoiceDetailResponse get(Long projectId, Long invoiceId) {
        return InvoiceDetailResponse.from(find(projectId, invoiceId));
    }

    /** Adds a line item to a draft invoice and reworks the invoice amount to match. */
    @Transactional
    public InvoiceDetailResponse addLineItem(Long projectId, Long invoiceId, LineItemRequest request) {
        Invoice invoice = findDraft(projectId, invoiceId);
        invoice.addLineItem(request.description().strip(), request.qty(), request.unitPrice());
        invoices.flush();
        return InvoiceDetailResponse.from(invoice);
    }

    /** Changes a line item on a draft invoice and reworks the invoice amount to match. */
    @Transactional
    public InvoiceDetailResponse updateLineItem(Long projectId, Long invoiceId, Long lineItemId,
            LineItemRequest request) {
        Invoice invoice = findDraft(projectId, invoiceId);
        InvoiceLineItem item = findLineItem(invoice, lineItemId);
        invoice.updateLineItem(item, request.description().strip(), request.qty(), request.unitPrice());
        invoices.flush();
        return InvoiceDetailResponse.from(invoice);
    }

    /** Removes a line item from a draft invoice and reworks the invoice amount to match. */
    @Transactional
    public InvoiceDetailResponse removeLineItem(Long projectId, Long invoiceId, Long lineItemId) {
        Invoice invoice = findDraft(projectId, invoiceId);
        invoice.removeLineItem(findLineItem(invoice, lineItemId));
        invoices.flush();
        return InvoiceDetailResponse.from(invoice);
    }

    /** Sends a draft invoice and records the sending in the audit log. */
    @Transactional
    public InvoiceResponse send(Long projectId, Long invoiceId) {
        Invoice invoice = find(projectId, invoiceId);
        if (invoice.getStatus() != InvoiceStatus.DRAFT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft invoice can be sent");
        }
        if (invoice.getAmount().signum() == 0) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Add a line item before sending the invoice");
        }
        invoice.markSent();
        invoices.flush();
        audit.record("INVOICE_SENT id=" + invoice.getId() + " amount=" + invoice.getAmount().toPlainString());
        return toResponse(invoice);
    }

    private InvoiceResponse toResponse(Invoice invoice) {
        return InvoiceResponse.from(invoice, payments.sumAmountByInvoiceId(invoice.getId()));
    }

    private Invoice find(Long projectId, Long invoiceId) {
        return invoices.findById(invoiceId)
                .filter(i -> i.getProject().getId().equals(projectId))
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown invoice"));
    }

    private Invoice findDraft(Long projectId, Long invoiceId) {
        Invoice invoice = find(projectId, invoiceId);
        if (invoice.getStatus() != InvoiceStatus.DRAFT) {
            throw new ResponseStatusException(HttpStatus.CONFLICT, "Only a draft invoice can be changed");
        }
        return invoice;
    }

    private static InvoiceLineItem findLineItem(Invoice invoice, Long lineItemId) {
        return invoice.findLineItem(lineItemId)
                .orElseThrow(() -> new ResponseStatusException(HttpStatus.NOT_FOUND, "Unknown line item"));
    }
}
package net.officefloor.hq.app.invoice;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.util.Collection;
import java.util.List;
import org.springframework.data.jpa.repository.JpaRepository;
import org.springframework.data.jpa.repository.Query;

public interface InvoiceRepository extends JpaRepository<Invoice, Long> {

    List<Invoice> findByProjectIdOrderById(Long projectId);

    /** All invoices across every project, with their project loaded in the same query. */
    @Query("SELECT i FROM Invoice i JOIN FETCH i.project ORDER BY i.id")
    List<Invoice> findAllWithProject();

    /** Invoices across every project at the given status, with their project loaded in the same query. */
    @Query("SELECT i FROM Invoice i JOIN FETCH i.project WHERE i.status = :status ORDER BY i.id")
    List<Invoice> findAllWithProjectByStatus(InvoiceStatus status);

    /** A client's invoices across all of their projects, with their project loaded in the same query. */
    @Query("SELECT i FROM Invoice i JOIN FETCH i.project p WHERE p.client.id = :clientId ORDER BY i.id")
    List<Invoice> findByClientIdWithProject(Long clientId);

    /** Sum of the amounts of all invoices with any of the given statuses (zero when there are none). */
    @Query("SELECT COALESCE(SUM(i.amount), 0) FROM Invoice i WHERE i.status IN :statuses")
    BigDecimal sumAmountByStatusIn(Collection<InvoiceStatus> statuses);

    /** Number of invoices with any of the given statuses whose due date is before the given date. */
    @Query("SELECT COUNT(i) FROM Invoice i WHERE i.status IN :statuses AND i.dueDate < :date")
    long countByStatusInAndDueDateBefore(Collection<InvoiceStatus> statuses, LocalDate date);
}
import { CurrencyPipe } from '@angular/common';
import { Component, computed, inject, signal } from '@angular/core';
import { rxResource } from '@angular/core/rxjs-interop';
import { RouterLink } from '@angular/router';
import { INVOICE_STATUSES, InvoiceService, InvoiceStatus } from './invoice.service';

// Invoices page: every invoice from every project in one list, showing the project each is for and
// the stage it is at. The list can be narrowed to a single stage.
@Component({
  selector: 'app-invoices',
  imports: [CurrencyPipe, RouterLink],
  template: `
    <h1>Invoices</h1>

    <label for="invoice-status-filter">Stage</label>
    <select
      id="invoice-status-filter"
      data-testid="invoice-status-filter"
      [value]="status()"
      (change)="onStatusChange($event)"
    >
      <option value="">All stages</option>
      @for (s of statuses; track s) {
        <option [value]="s">{{ s }}</option>
      }
    </select>

    @if (invoices.error()) {
      <p role="alert" data-testid="all-invoices-error">Could not load the invoices.</p>
    } @else if (invoices.isLoading()) {
      <p data-testid="all-invoices-loading">Loading invoices…</p>
    } @else if (list().length === 0) {
      <p data-testid="all-invoices-empty">
        {{ status() ? 'No invoices at the ' + status() + ' stage.' : 'No invoices yet.' }}
      </p>
    } @else {
      <table data-testid="all-invoices-table">
        <caption>All invoices across every project</caption>
        <thead>
          <tr>
            <th scope="col">Invoice</th>
            <th scope="col">Project</th>
            <th scope="col">Amount</th>
            <th scope="col">Status</th>
            <th scope="col">Issued</th>
            <th scope="col">Due</th>
          </tr>
        </thead>
        <tbody>
          @for (i of list(); track i.id) {
            <tr [attr.data-testid]="'invoice-row-' + i.id">
              <td data-testid="invoice-id">#{{ i.id }}</td>
              <td data-testid="invoice-project">
                <a [routerLink]="['/projects', i.projectId]">{{ i.projectName }}</a>
              </td>
              <td data-testid="invoice-amount">{{ i.amount | currency: 'USD' : 'symbol' : '1.2-2' : 'en-US' }}</td>
              <td data-testid="invoice-status">{{ i.status }}</td>
              <td data-testid="invoice-issued">{{ i.issuedDate }}</td>
              <td data-testid="invoice-due">{{ i.dueDate }}</td>
            </tr>
          }
        </tbody>
      </table>
    }
  `,
})
export class Invoices {
  private readonly service = inject(InvoiceService);

  protected readonly statuses = INVOICE_STATUSES;
  /** The stage the list is narrowed to; empty for every stage. */
  protected readonly status = signal<InvoiceStatus | ''>('');

  protected readonly invoices = rxResource({
    params: () => this.status(),
    stream: ({ params }) => this.service.listAll(params || undefined),
  });
  protected readonly list = computed(() => (this.invoices.hasValue() ? this.invoices.value() : []));

  protected onStatusChange(event: Event): void {
    this.status.set((event.target as HTMLSelectElement).value as InvoiceStatus | '');
  }
}
import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';

export const INVOICE_STATUSES = ['DRAFT', 'SENT', 'PARTIAL', 'PAID'] as const;

export type InvoiceStatus = (typeof INVOICE_STATUSES)[number];

export interface Invoice {
  id: number;
  projectId: number;
  amount: number;
  status: InvoiceStatus;
  /** ISO date (yyyy-MM-dd) the invoice was issued. */
  issuedDate: string;
  /** ISO date (yyyy-MM-dd) payment is due. */
  dueDate: string;
}

/** An invoice as listed for its project, with how much is still left to pay after any payments. */
export interface ProjectInvoice extends Invoice {
  amountDue: number;
}

/** An invoice as listed across all projects, with the name of the project it is for. */
export interface InvoiceSummary extends Invoice {
  projectName: string;
}

/** An invoice as listed on a client's statement: its project's name and how much is left to pay. */
export interface StatementInvoice extends ProjectInvoice {
  projectName: string;
}

/** A client's invoices across all their projects, with the total they still owe. */
export interface ClientStatement {
  clientId: number;
  clientName: string;
  invoices: StatementInvoice[];
  outstanding: number;
}

/** One thing an invoice charges for; its amount is quantity times unit price. */
export interface LineItem {
  id: number;
  description: string;
  qty: number;
  unitPrice: number;
  amount: number;
}

/** A single invoice with the line items it is built from. */
export interface InvoiceDetail extends Invoice {
  lineItems: LineItem[];
}

export interface NewLineItem {
  description: string;
  qty: number;
  unitPrice: number;
}

export interface NewInvoice {
  /** Raises the invoice as one figure; omit to start an empty draft built up from line items. */
  amount?: number;
  /** Defaults to today on the server when omitted. */
  issuedDate?: string;
  /** Defaults to 30 days after the issue date on the server when omitted. */
  dueDate?: string;
}

@Injectable({ providedIn: 'root' })
export class InvoiceService {
  private readonly http = inject(HttpClient);

  /** Every invoice across all projects, optionally narrowed to one status. */
  listAll(status?: InvoiceStatus): Observable<InvoiceSummary[]> {
    const params: Record<string, string> = status ? { status } : {};
    return this.http.get<InvoiceSummary[]>('/api/invoices', { params });
  }

  listForProject(projectId: number): Observable<ProjectInvoice[]> {
    return this.http.get<ProjectInvoice[]>(`/api/projects/${projectId}/invoices`);
  }

  statementForClient(clientId: number): Observable<ClientStatement> {
    return this.http.get<ClientStatement>(`/api/clients/${clientId}/statement`);
  }

  create(projectId: number, invoice: NewInvoice): Observable<ProjectInvoice> {
    return this.http.post<ProjectInvoice>(`/api/projects/${projectId}/invoices`, invoice);
  }

  get(projectId: number, invoiceId: number): Observable<InvoiceDetail> {
    return this.http.get<InvoiceDetail>(`/api/projects/${projectId}/invoices/${invoiceId}`);
  }

  addLineItem(projectId: number, invoiceId: number, item: NewLineItem): Observable<InvoiceDetail> {
    return this.http.post<InvoiceDetail>(`/api/projects/${projectId}/invoices/${invoiceId}/line-items`, item);
  }

  updateLineItem(projectId: number, invoiceId: number, lineItemId: number, item: NewLineItem): Observable<InvoiceDetail> {
    return this.http.put<InvoiceDetail>(
      `/api/projects/${projectId}/invoices/${invoiceId}/line-items/${lineItemId}`,
      item,
    );
  }

  removeLineItem(projectId: number, invoiceId: number, lineItemId: number): Observable<InvoiceDetail> {
    return this.http.delete<InvoiceDetail>(`/api/projects/${projectId}/invoices/${invoiceId}/line-items/${lineItemId}`);
  }

  send(projectId: number, invoiceId: number): Observable<ProjectInvoice> {
    return this.http.post<ProjectInvoice>(`/api/projects/${projectId}/invoices/${invoiceId}/send`, null);
  }
}

